docker pull quay.io/frrouting/frr:10.7.0;
RC=$?;
if [ "$RC" = "0" ]; then echo "Done. quay.io/frrouting/frr:10.7.0 is ready."; else echo "FAILED to pull quay.io/frrouting/frr:10.7.0 (rc=$RC)"; fi;
mysql pnetlab_db -e "DELETE FROM process_device WHERE process_device_id='{device_id}'"

device_delete:
echo "Removing quay.io/frrouting/frr:10.7.0...";
docker rmi quay.io/frrouting/frr:10.7.0;
mysql pnetlab_db -e "DELETE FROM process_device WHERE process_device_id='{device_id}'"

device_script:
F=/opt/unetlab/addons/docker-store/pnet-azure-1-0.tar.gz;
if [ -f "$F" ]; then
  echo "Loading pnet-azure:1.0 from local image store...";
  docker -H=unix:///var/run/docker.sock load -i "$F"; RC=$?;
else
  echo "No local image store copy, pulling rspnet/pnet-azure:latest from Docker Hub...";
  docker -H=unix:///var/run/docker.sock pull rspnet/pnet-azure:latest; RC=$?;
  if [ "$RC" = "0" ]; then docker -H=unix:///var/run/docker.sock tag rspnet/pnet-azure:latest pnet-azure:1.0; RC=$?; fi;
fi;
if [ "$RC" = "0" ]; then echo "Done. pnet-azure:1.0 is ready."; else echo "FAILED to load/pull pnet-azure (rc=$RC)"; fi;
mysql pnetlab_db -e "DELETE FROM process_device WHERE process_device_id='{device_id}'"

device_delete:
echo "Removing pnet-azure:1.0...";
docker -H=unix:///var/run/docker.sock rmi pnet-azure:1.0 2>/dev/null; docker -H=unix:///var/run/docker.sock rmi rspnet/pnet-azure:latest 2>/dev/null;
mysql pnetlab_db -e "DELETE FROM process_device WHERE process_device_id='{device_id}'"

